import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { Project } from '@/types'
import { useLocalizedData } from '@/composables/useLocalizedData'

export const useProjectsStore = defineStore('projects', () => {
  const { createLocalizedRef, loadProjectsData } = useLocalizedData()

  // Utiliser createLocalizedRef pour avoir des données réactives
  const projects = createLocalizedRef<Project[]>('projects', [])
  const loading = ref(false)
  const error = ref<string | null>(null)

  // Computed
  const visibleProjects = computed(() => projects.value.filter((project) => !project.hidden))

  const featuredProjects = computed(() =>
    visibleProjects.value.filter((project) => project.featured)
  )

  const projectsByCategory = computed(() => {
    const categories: Record<string, Project[]> = {}
    visibleProjects.value.forEach((project) => {
      if (!categories[project.category]) {
        categories[project.category] = []
      }
      categories[project.category]?.push(project)
    })
    return categories
  })

  const categories = computed(() => [...new Set(visibleProjects.value.map((p) => p.category))])

  // Actions
  const loadProjects = async () => {
    loading.value = true
    error.value = null

    const data = await loadProjectsData()
    if (data) {
      projects.value = data as Project[]
    } else {
      error.value = 'Failed to load projects'
    }

    loading.value = false
  }

  const getProjectBySlug = (slug: string) => {
    return visibleProjects.value.find((project) => project.slug === slug)
  }

  const getProjectsByTechnology = (tech: string) => {
    return visibleProjects.value.filter((project) =>
      project.technologies.some((t) => t.toLowerCase().includes(tech.toLowerCase()))
    )
  }

  const searchProjects = (query: string) => {
    const searchTerm = query.toLowerCase()
    return visibleProjects.value.filter(
      (project) =>
        project.title.toLowerCase().includes(searchTerm) ||
        project.description.toLowerCase().includes(searchTerm) ||
        project.technologies.some((tech) => tech.toLowerCase().includes(searchTerm)) ||
        project.category.toLowerCase().includes(searchTerm)
    )
  }

  return {
    // State
    projects,
    loading,
    error,

    // Getters
    visibleProjects,
    featuredProjects,
    projectsByCategory,
    categories,

    // Actions
    loadProjects,
    getProjectBySlug,
    getProjectsByTechnology,
    searchProjects,
  }
})
